        return array[i];
    }

    int size() {
        return size;
    }
};

struct NumberTheory {
    struct Modulus {
        IntStack factorial;
        IntStack invFactorial;

        Modulus() {
            factorial.push(1);
            invFactorial.push(1);
        }

        virtual long long modulus() const = 0;

        long long fact(int n) {
            while ((int)factorial.size() <= n) {
                factorial.push((int)mult(factorial.get(factorial.size() - 1), factorial.size()));
            }
            return factorial.get(n);
        }

        long long fInv(int n) {
            int lastKnown = invFactorial.size() - 1;
            if (lastKnown < n) {
                std::vector<long long> fInv(n - lastKnown);
                fInv[0] = inv(fact(n));
                for (int i = 1; i < (int)fInv.size(); i++) {
                    fInv[i] = mult(fInv[i - 1], n - i + 1);
                }
                for (int i = (int)fInv.size() - 1; i >= 0; i--) {
                    invFactorial.push((int)fInv[i]);
                }
            }
            return invFactorial.get(n);
        }

        long long paritySign(long long k) {
            return (k & 1) ? modulus() - 1 : 1;
        }

        long long ncr(int n, int r) {
            if (n < 0 || r < 0 || n < r) return 0;
            return mult(fact(n), mult(fInv(r), fInv(n - r)));
        }

        long long smallInv(int n) {
            return mult(fInv(n), fact(n - 1));
        }

        long long normalize(long long x) {
            x %= modulus();
            if (x < 0) x += modulus();
            return x;
        }

        long long add(long long a, long long b) {
            long long v = a + b;
            return v < modulus() ? v : v - modulus();
        }

        long long mult(long long... x) {
            long long r = 1;
            for (auto i : x) r = mult(r, i);
            return r;
        }

        long long mult(long long a, long long b) {
            return (a * b) % modulus();
        }

        long long inv(long long value) {
            long long g = modulus(), x = 0, y = 1;
            for (long long r = value; r != 0; ) {
                long long q = g / r;
                g %= r;
                long long temp = g;
                g = r;
                r = temp;
                x -= q * y;
                temp = x;
                x = y;
                y = temp;
            }
            if (g != 1) throw std::runtime_error("No inverse");
            return normalize(x);
        }
    };

    struct Mod998 : public Modulus {
        long long modulus() const override {
            return 998244353LL;
        }
    };
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;

    NumberTheory::Mod998 mod;
    mod.fInv(n + m);

    long long phaseSize = 1;
    long long p = 1;
    for (int i = 0; ; i++) {
        p = mod.mult(p, n - i, mod.smallInv(n + m - i));
        if (p == 0) break;
        phaseSize = mod.add(phaseSize, p);
    }

    long long answer = 0;
    for (int k = 1; k <= n; k++) {
        long long sign = mod.paritySign(k + 1);
        long long numPhases = mod.mult(m + k, mod.smallInv(k));
        long long term = mod.mult(sign, mod.ncr(n, k), numPhases, phaseSize);
        answer = mod.add(answer, term);
    }

    cout << answer << "\n";

    return 0;
}

